import { useEffect, useState } from 'react'
import ProductPicker from '../components/ProductPicker.jsx'
import { enhanceImage, getImageCapabilities, updateProduct } from '../services/api.js'
import { useAuth } from '../services/AuthContext.jsx'

// Friendly names for whatever engine actually ran, so the artisan always
// knows what happened to their photo.
const ENGINE_LABELS = {
  openai: { text: 'Enhanced by OpenAI', style: 'bg-forest text-white' },
  gemini: { text: 'Enhanced by Gemini AI', style: 'bg-forest text-white' },
  'local-ai': { text: 'Background removed on this computer', style: 'bg-forest text-white' },
  basic: { text: 'Basic enhancement only', style: 'bg-sand text-charcoal' },
}

export default function PhotoStudio() {
  const { token } = useAuth()

  const [product, setProduct] = useState(null)
  const [file, setFile] = useState(null)
  const [originalPreview, setOriginalPreview] = useState(null)

  const [engine, setEngine] = useState('auto')
  const [instruction, setInstruction] = useState('')
  const [brightness, setBrightness] = useState(1.15)
  const [contrast, setContrast] = useState(1.15)
  const [removeBg, setRemoveBg] = useState(true)

  const [caps, setCaps] = useState(null)

  const [enhancedPreview, setEnhancedPreview] = useState(null)
  const [enhancedBlob, setEnhancedBlob] = useState(null)
  const [engineUsed, setEngineUsed] = useState('')
  const [note, setNote] = useState('')

  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [saved, setSaved] = useState(false)

  useEffect(() => {
    getImageCapabilities(token)
      .then((c) => {
        setCaps(c)
        setEngine(c.default_engine === 'openai' || c.default_engine === 'gemini' ? c.default_engine : 'local')
      })
      .catch(() => setCaps({ openai_available: false, gemini_available: false, background_removal_available: false }))
  }, [token])

  function handleFileChange(e) {
    const f = e.target.files?.[0]
    if (!f) return
    setFile(f)
    setOriginalPreview(URL.createObjectURL(f))
    setEnhancedPreview(null)
    setEnhancedBlob(null)
    setSaved(false)
    setNote('')
  }

  async function handleEnhance() {
    if (!file) return
    setError('')
    setLoading(true)
    try {
      const result = await enhanceImage(
        file,
        { engine, removeBg, brightness, contrast, instruction },
        token
      )
      setEnhancedBlob(result.blob)
      setEnhancedPreview(URL.createObjectURL(result.blob))
      setEngineUsed(result.engineUsed)
      setNote(result.note)
      setSaved(false)
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  async function handleSave() {
    if (!enhancedBlob || !product) return
    setError('')
    setLoading(true)
    try {
      const formData = new FormData()
      formData.append('name', product.name)
      formData.append('name_hindi', product.name_hindi || '')
      formData.append('description_english', product.description_english || '')
      formData.append('description_hindi', product.description_hindi || '')
      formData.append('material', product.material || '')
      formData.append('category', product.category || '')
      formData.append('craft_type', product.craft_type || '')
      formData.append('price', product.price ?? '')
      formData.append('status', product.status)
      formData.append('image', enhancedBlob, 'enhanced.png')

      const updated = await updateProduct(product.id, formData, token)
      setProduct(updated)
      setSaved(true)
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  const openaiReady = caps?.openai_available
  const geminiReady = caps?.gemini_available
  const aiReady = openaiReady || geminiReady
  const aiEngine = openaiReady ? 'openai' : 'gemini'
  const badge = ENGINE_LABELS[engineUsed]

  return (
    <div>
      <ProductPicker
        selectedId={product?.id}
        onSelect={(p) => { setProduct(p); setEnhancedPreview(null); setSaved(false); setNote('') }}
      />

      {product && (
        <div className="p-5">
          <label className="block text-sm font-medium text-charcoal mb-1">1. Choose a photo</label>
          <input
            type="file"
            accept="image/jpeg,image/png,image/webp"
            capture="environment"
            onChange={handleFileChange}
            className="text-sm mb-4 block"
          />

          {originalPreview && (
            <div className="bg-white rounded-xl p-4 shadow-sm mb-4">
              <p className="text-sm font-medium text-charcoal mb-2">2. Choose how to enhance</p>

              {/* ---- Engine choice ---- */}
              <button
                type="button"
                onClick={() => aiReady && setEngine(aiEngine)}
                disabled={!aiReady}
                className={`w-full text-left p-3 rounded-lg border mb-2 ${
                  engine === 'openai' || engine === 'gemini'
                    ? 'border-forest bg-ivory'
                    : 'border-gray-300 bg-white'
                } ${!aiReady ? 'opacity-60' : ''}`}
              >
                <span className="font-semibold text-forest">✨ AI Photo Studio</span>
                <span className="block text-xs text-gray-600 mt-1">
                  Real AI re-shoots your photo: clean studio background, correct lighting,
                  sharper craft detail — while keeping the product exactly as it is.
                </span>
                {aiReady && (
                  <span className="block text-xs text-gray-400 mt-1">
                    Powered by {openaiReady ? 'OpenAI' : 'Gemini'}
                  </span>
                )}
                {!aiReady && (
                  <span className="block text-xs text-terracotta font-medium mt-1">
                    Needs an OpenAI or Google AI key in backend/.env — see SETUP_GUIDE.md
                  </span>
                )}
              </button>

              <button
                type="button"
                onClick={() => setEngine('local')}
                className={`w-full text-left p-3 rounded-lg border ${
                  engine === 'local' ? 'border-forest bg-ivory' : 'border-gray-300 bg-white'
                }`}
              >
                <span className="font-semibold text-forest">🛠️ Basic enhance (works offline)</span>
                <span className="block text-xs text-gray-600 mt-1">
                  Background removal and brightness/contrast on this computer. No internet needed.
                </span>
              </button>

              {/* ---- Engine-specific controls ---- */}
              {(engine === 'openai' || engine === 'gemini') && (
                <div className="mt-3">
                  <label className="text-sm text-gray-600">
                    Anything extra to tell the AI? (optional)
                  </label>
                  <input
                    className="w-full p-2 rounded-lg border border-gray-300 text-sm mt-1"
                    value={instruction}
                    onChange={(e) => setInstruction(e.target.value)}
                    placeholder="e.g. show it on a plain white background"
                  />
                </div>
              )}

              {engine === 'local' && (
                <div className="mt-3">
                  <img
                    src={originalPreview}
                    alt="Preview"
                    className="w-full h-48 object-cover rounded-lg mb-3"
                    style={{ filter: `brightness(${brightness}) contrast(${contrast})` }}
                  />

                  <label className="text-sm text-gray-600">Brightness</label>
                  <input type="range" min="0.7" max="1.6" step="0.05" value={brightness}
                    onChange={(e) => setBrightness(Number(e.target.value))} className="w-full mb-3" />

                  <label className="text-sm text-gray-600">Contrast</label>
                  <input type="range" min="0.7" max="1.6" step="0.05" value={contrast}
                    onChange={(e) => setContrast(Number(e.target.value))} className="w-full mb-3" />

                  <label className="flex items-center gap-2 text-sm text-gray-700">
                    <input type="checkbox" checked={removeBg} onChange={(e) => setRemoveBg(e.target.checked)} />
                    Remove background
                  </label>
                  {removeBg && caps?.background_removal_available === false && (
                    <p className="text-xs text-terracotta font-medium mt-1">
                      The background-removal engine isn't loading on this backend, so the photo
                      will be brightened but the background kept.
                      {caps?.unavailable_reason ? ` (${caps.unavailable_reason})` : ''}
                    </p>
                  )}
                </div>
              )}

              <button
                onClick={handleEnhance}
                disabled={loading}
                className="w-full bg-terracotta text-white font-semibold py-3 rounded-full mt-4 shadow-md disabled:opacity-60"
              >
                {loading
                  ? ((engine === 'openai' || engine === 'gemini') ? 'AI is re-shooting your photo…' : 'Enhancing…')
                  : '✨ Enhance Photo'}
              </button>
              {loading && (engine === 'openai' || engine === 'gemini') && (
                <p className="text-xs text-gray-500 text-center mt-2">
                  This can take up to a minute. Please keep this screen open.
                </p>
              )}
            </div>
          )}

          {enhancedPreview && (
            <div className="bg-white rounded-xl p-4 shadow-sm">
              <div className="flex items-center justify-between mb-3">
                <p className="text-sm font-medium text-charcoal">3. Before → After</p>
                {badge && (
                  <span className={`text-xs font-semibold px-2 py-1 rounded-full ${badge.style}`}>
                    {badge.text}
                  </span>
                )}
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <p className="text-xs text-gray-500 mb-1 text-center">Before</p>
                  <img src={originalPreview} alt="Before" className="w-full h-40 object-cover rounded-lg" />
                </div>
                <div>
                  <p className="text-xs text-gray-500 mb-1 text-center">After</p>
                  <img src={enhancedPreview} alt="After" className="w-full h-40 object-cover rounded-lg border border-gray-200" />
                </div>
              </div>

              {note && <p className="text-xs text-gray-500 mt-2">{note}</p>}
              {error && <p className="text-red-600 text-sm mt-3">{error}</p>}
              {saved && <p className="text-forest text-sm mt-3">Saved to product ✓</p>}

              <button
                onClick={handleSave}
                disabled={loading}
                className="w-full bg-forest text-white font-semibold py-3 rounded-full mt-4 shadow-md disabled:opacity-60"
              >
                {loading ? 'Saving...' : 'Save to Product'}
              </button>
            </div>
          )}

          {error && !enhancedPreview && <p className="text-red-600 text-sm mt-3">{error}</p>}
        </div>
      )}
    </div>
  )
}

import { useState } from 'react'
import ProductPicker from '../components/ProductPicker.jsx'
import { getPricingSuggestion } from '../services/api.js'
import { useAuth } from '../services/AuthContext.jsx'

export default function Pricing() {
  const { token } = useAuth()
  const [product, setProduct] = useState(null)
  const [costs, setCosts] = useState({ material_cost: '', labour_cost: '', packaging_cost: '', other_cost: '' })
  const [result, setResult] = useState(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [applied, setApplied] = useState(false)

  function handleChange(e) {
    setCosts({ ...costs, [e.target.name]: e.target.value })
    setApplied(false)
  }

  async function handleCalculate() {
    setError('')
    setLoading(true)
    try {
      const data = await getPricingSuggestion(
        {
          product_id: product?.id,
          material_cost: Number(costs.material_cost) || 0,
          labour_cost: Number(costs.labour_cost) || 0,
          packaging_cost: Number(costs.packaging_cost) || 0,
          other_cost: Number(costs.other_cost) || 0,
          category: product?.category || 'Other',
          save: false,
        },
        token
      )
      setResult(data)
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  async function handleApply() {
    if (!result || !product) return
    setLoading(true)
    setError('')
    try {
      await getPricingSuggestion(
        {
          product_id: product.id,
          material_cost: Number(costs.material_cost) || 0,
          labour_cost: Number(costs.labour_cost) || 0,
          packaging_cost: Number(costs.packaging_cost) || 0,
          other_cost: Number(costs.other_cost) || 0,
          category: product.category || 'Other',
          save: true,
        },
        token
      )
      setApplied(true)
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  const inputClass = 'w-full p-3 rounded-lg border border-gray-300 focus:border-forest focus:outline-none text-base'
  const labelClass = 'block text-sm font-medium text-charcoal mb-1 mt-3'

  return (
    <div>
      <ProductPicker selectedId={product?.id} onSelect={(p) => { setProduct(p); setResult(null) }} />

      {product && (
        <div className="p-5">
          <div className="bg-white rounded-xl p-4 shadow-sm mb-4">
            <p className="text-sm text-gray-500 mb-2">Enter your costs to make ONE {product.name}</p>

            <label className={labelClass}>Raw Material Cost (₹)</label>
            <input className={inputClass} type="number" min="0" name="material_cost" value={costs.material_cost} onChange={handleChange} />

            <label className={labelClass}>Labour Cost (₹)</label>
            <input className={inputClass} type="number" min="0" name="labour_cost" value={costs.labour_cost} onChange={handleChange} />

            <label className={labelClass}>Packaging Cost (₹)</label>
            <input className={inputClass} type="number" min="0" name="packaging_cost" value={costs.packaging_cost} onChange={handleChange} />

            <label className={labelClass}>Other Cost (transport, etc.) (₹)</label>
            <input className={inputClass} type="number" min="0" name="other_cost" value={costs.other_cost} onChange={handleChange} />

            {error && <p className="text-red-600 text-sm mt-3">{error}</p>}

            <button
              onClick={handleCalculate}
              disabled={loading}
              className="w-full bg-terracotta text-white font-semibold py-3 rounded-full mt-4 shadow-md disabled:opacity-60"
            >
              {loading ? 'Calculating...' : '💰 Suggest a Price'}
            </button>
          </div>

          {result && (
            <div className="bg-white rounded-xl p-4 shadow-sm">
              <div className="grid grid-cols-3 gap-2 text-center mb-4">
                <div>
                  <p className="text-xs text-gray-500">Production Cost</p>
                  <p className="text-lg font-bold text-charcoal">₹{result.production_cost}</p>
                </div>
                <div>
                  <p className="text-xs text-gray-500">Suggested Range</p>
                  <p className="text-lg font-bold text-charcoal">₹{result.suggested_min}–₹{result.suggested_max}</p>
                </div>
                <div>
                  <p className="text-xs text-gray-500">Recommended</p>
                  <p className="text-lg font-bold text-terracotta">₹{result.recommended_price}</p>
                </div>
              </div>

              <p className="text-sm text-gray-700 bg-ivory rounded-lg p-3 mb-3">{result.explanation}</p>
              <p className="text-xs text-gray-400 mb-4">
                Reference data source: {result.data_source} ({result.reference_sample_size} sample prices considered)
              </p>

              {applied && <p className="text-forest text-sm mb-3">Applied ₹{result.recommended_price} to this product ✓</p>}

              <button
                onClick={handleApply}
                disabled={loading}
                className="w-full bg-forest text-white font-semibold py-3 rounded-full shadow-md disabled:opacity-60"
              >
                {loading ? 'Applying...' : `Use ₹${result.recommended_price} as this product's price`}
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import { listProducts, deleteProduct, imageUrl } from '../services/api.js'
import { useAuth } from '../services/AuthContext.jsx'
import ProductForm from '../components/ProductForm.jsx'
import { themeFor } from '../theme/categoryTheme.js'

function StatusBadge({ status }) {
  const isPublished = status === 'published'
  return (
    <span
      className={`text-xs font-semibold px-2 py-1 rounded-full ${
        isPublished ? 'bg-forest text-white' : 'bg-sand text-charcoal'
      }`}
    >
      {isPublished ? 'Published' : 'Draft'}
    </span>
  )
}

export default function Products() {
  const { token } = useAuth()
  const [searchParams, setSearchParams] = useSearchParams()
  const [products, setProducts] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  // Support jumping straight to the add-product form via the "+" floating
  // button elsewhere in the app (/products?new=1), not just the in-page button.
  const [view, setView] = useState(searchParams.get('new') === '1' ? 'form' : 'list') // 'list' | 'form'
  const [editingProduct, setEditingProduct] = useState(null)

  async function loadProducts() {
    setLoading(true)
    setError('')
    try {
      const data = await listProducts(token)
      setProducts(data)
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadProducts()
    if (searchParams.get('new') === '1') {
      setSearchParams({}, { replace: true }) // clean the URL once we've consumed it
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  function handleAddNew() {
    setEditingProduct(null)
    setView('form')
  }

  function handleEdit(product) {
    setEditingProduct(product)
    setView('form')
  }

  function handleSaved() {
    setView('list')
    setEditingProduct(null)
    loadProducts()
  }

  async function handleDelete(product) {
    const sure = window.confirm(`Delete "${product.name}"? This cannot be undone.`)
    if (!sure) return
    try {
      await deleteProduct(product.id, token)
      loadProducts()
    } catch (err) {
      alert(err.message)
    }
  }

  if (view === 'form') {
    return (
      <ProductForm
        existingProduct={editingProduct}
        onSaved={handleSaved}
        onCancel={() => setView('list')}
      />
    )
  }

  return (
    <div className="p-5">
      <button
        onClick={handleAddNew}
        className="w-full bg-terracotta text-white font-semibold py-3 rounded-full shadow-md mb-5"
      >
        + Add Product
      </button>

      {loading && (
        <div className="space-y-3">
          {[0, 1, 2].map((i) => (
            <div key={i} className="bg-white rounded-2xl shadow-sm p-3 flex gap-3">
              <div className="skeleton w-24 h-24 rounded-xl flex-shrink-0" />
              <div className="flex-1 py-1 space-y-2">
                <div className="skeleton h-4 rounded-full w-3/4" />
                <div className="skeleton h-3 rounded-full w-1/2" />
                <div className="skeleton h-3 rounded-full w-1/3" />
              </div>
            </div>
          ))}
        </div>
      )}
      {error && <p className="text-red-600 text-center">{error}</p>}

      {!loading && products.length === 0 && (
        <div className="text-center mt-10 text-gray-500">
          <div className="text-4xl mb-2">📦</div>
          <p>You haven't added any products yet.</p>
        </div>
      )}

      <div className="space-y-3">
        {products.map((p) => (
          <div key={p.id} className="fade-in bg-white rounded-2xl shadow-sm p-3 flex gap-3">
            {p.image_url ? (
              <img src={imageUrl(p.image_url)} alt={p.name} className="w-24 h-24 object-cover rounded-xl flex-shrink-0" />
            ) : (
              <div
                className="w-24 h-24 rounded-xl flex items-center justify-center text-3xl flex-shrink-0"
                style={{ backgroundColor: themeFor(p.category).color }}
              >
                {themeFor(p.category).emoji}
              </div>
            )}

            <div className="flex-1 min-w-0">
              <div className="flex items-center justify-between gap-2">
                <h3 className="font-semibold text-charcoal truncate">{p.name}</h3>
                <StatusBadge status={p.status} />
              </div>
              {p.price != null && <p className="text-terracotta font-semibold">₹{p.price}</p>}
              <p className="text-xs text-gray-500 truncate">{p.category}</p>

              <div className="flex gap-3 mt-2">
                <button onClick={() => handleEdit(p)} className="text-sm text-forest font-medium">Edit</button>
                <button onClick={() => handleDelete(p)} className="text-sm text-red-600 font-medium">Delete</button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

import { useState } from 'react'
import { useNavigate, Link } from 'react-router-dom'
import { useAuth } from '../services/AuthContext.jsx'
import { updateMe } from '../services/api.js'
import { CRAFT_CATEGORIES, INDIAN_STATES, LANGUAGES } from '../constants.js'

export default function Profile() {
  const { user, token, setUser, logout } = useAuth()
  const navigate = useNavigate()

  const [form, setForm] = useState({
    name: user?.name || '',
    email: user?.email || '',
    preferred_language: user?.preferred_language || 'Hindi',
    business_name: user?.business?.business_name || '',
    craft_category: user?.business?.craft_category || CRAFT_CATEGORIES[0],
    description: user?.business?.description || '',
    location: user?.business?.location || '',
    state: user?.business?.state || INDIAN_STATES[0],
  })
  const [saved, setSaved] = useState(false)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)

  function handleChange(e) {
    setForm({ ...form, [e.target.name]: e.target.value })
    setSaved(false)
  }

  async function handleSave(e) {
    e.preventDefault()
    setError('')
    setLoading(true)
    try {
      const updated = await updateMe(form, token)
      setUser(updated)
      setSaved(true)
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  function handleLogout() {
    logout()
    navigate('/')
  }

  const inputClass =
    'w-full p-3 rounded-lg border border-gray-300 focus:border-forest focus:outline-none text-base'
  const labelClass = 'block text-sm font-medium text-charcoal mb-1 mt-4'

  if (!user) return null

  return (
    <div className="p-5">
      <form onSubmit={handleSave}>
        <label className={labelClass}>Your Name</label>
        <input className={inputClass} name="name" value={form.name} onChange={handleChange} />

        <label className={labelClass}>Email</label>
        <input className={inputClass} type="email" name="email" value={form.email} onChange={handleChange} />

        <label className={labelClass}>Preferred Language</label>
        <select className={inputClass} name="preferred_language" value={form.preferred_language} onChange={handleChange}>
          {LANGUAGES.map((lang) => <option key={lang} value={lang}>{lang}</option>)}
        </select>

        <hr className="my-6 border-gray-200" />
        <h2 className="text-lg font-semibold text-forest mb-2">Your Business</h2>

        <label className={labelClass}>Business / Craft Name</label>
        <input className={inputClass} name="business_name" value={form.business_name} onChange={handleChange} />

        <label className={labelClass}>Craft Category</label>
        <select className={inputClass} name="craft_category" value={form.craft_category} onChange={handleChange}>
          {CRAFT_CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
        </select>

        <label className={labelClass}>Describe your business</label>
        <textarea className={inputClass} name="description" rows={3} value={form.description} onChange={handleChange} />

        <label className={labelClass}>Location (City/Town)</label>
        <input className={inputClass} name="location" value={form.location} onChange={handleChange} />

        <label className={labelClass}>State</label>
        <select className={inputClass} name="state" value={form.state} onChange={handleChange}>
          {INDIAN_STATES.map((s) => <option key={s} value={s}>{s}</option>)}
        </select>

        {error && <p className="text-red-600 text-sm mt-4">{error}</p>}
        {saved && <p className="text-forest text-sm mt-4">Profile updated.</p>}

        <button
          type="submit"
          disabled={loading}
          className="w-full bg-forest text-white font-semibold py-3 rounded-full mt-6 shadow-md disabled:opacity-60"
        >
          {loading ? 'Saving...' : 'Save Changes'}
        </button>
      </form>

      <Link
        to="/help"
        className="block w-full text-center border border-forest text-forest font-semibold py-3 rounded-full mt-4"
      >
        Help & Support
      </Link>

      <button
        onClick={handleLogout}
        className="w-full border border-terracotta text-terracotta font-semibold py-3 rounded-full mt-3"
      >
        Log Out
      </button>
    </div>
  )
}

import { useEffect, useState } from 'react'
