import { useState, useEffect } from 'react'
import { useNavigate, Link } from 'react-router-dom'
import { registerUser, getSecurityQuestions } from '../services/api.js'
import { useAuth } from '../services/AuthContext.jsx'
import { CRAFT_CATEGORIES, INDIAN_STATES, LANGUAGES } from '../constants.js'

const emptyForm = {
  name: '',
  phone: '',
  email: '',
  password: '',
  preferred_language: 'Hindi',
  security_question: '',
  security_answer: '',
  business_name: '',
  craft_category: CRAFT_CATEGORIES[0],
  description: '',
  location: '',
  state: INDIAN_STATES[0],
}

export default function Register() {
  const [form, setForm] = useState(emptyForm)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const [questions, setQuestions] = useState([])
  const [questionsError, setQuestionsError] = useState('')
  const { login } = useAuth()
  const navigate = useNavigate()

  // Load the security questions from the backend when the page opens, and
  // pre-select the first one so the field is never left empty by accident.
  useEffect(() => {
    getSecurityQuestions()
      .then((data) => {
        setQuestions(data.questions)
        setForm((f) => (f.security_question ? f : { ...f, security_question: data.questions[0].id }))
      })
      .catch((err) => setQuestionsError(err.message))
  }, [])

  function handleChange(e) {
    setForm({ ...form, [e.target.name]: e.target.value })
  }

  async function handleSubmit(e) {
    e.preventDefault()
    setError('')

    if (form.password.length < 6) {
      setError('Password must be at least 6 characters.')
      return
    }

    if (!form.security_question) {
      setError('Please choose a security question.')
      return
    }

    if (form.security_answer.trim().length < 2) {
      setError('Please write the answer to your security question.')
      return
    }

    setLoading(true)
    try {
      const data = await registerUser({
        ...form,
        email: form.email || null,
      })
      login(data.access_token, data.user)
      navigate('/dashboard')
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  const inputClass =
    'w-full p-3 rounded-lg border border-gray-300 focus:border-forest focus:outline-none text-base'
  const labelClass = 'block text-sm font-medium text-charcoal mb-1 mt-4'

  return (
    <div className="min-h-screen bg-ivory px-5 py-8">
      <h1 className="text-2xl font-bold text-forest mb-1">Create your account</h1>
      <p className="text-gray-600 mb-4">Tell us about you and your craft.</p>

      <form onSubmit={handleSubmit}>
        <label className={labelClass}>Your Name</label>
        <input className={inputClass} name="name" value={form.name} onChange={handleChange} required />

        <label className={labelClass}>Phone Number</label>
        <input className={inputClass} name="phone" value={form.phone} onChange={handleChange} required />

        <label className={labelClass}>Email (optional)</label>
        <input className={inputClass} type="email" name="email" value={form.email} onChange={handleChange} />

        <label className={labelClass}>Password</label>
        <input className={inputClass} type="password" name="password" value={form.password} onChange={handleChange} required />

        <label className={labelClass}>Preferred Language</label>
        <select className={inputClass} name="preferred_language" value={form.preferred_language} onChange={handleChange}>
          {LANGUAGES.map((lang) => <option key={lang} value={lang}>{lang}</option>)}
        </select>

        <hr className="my-6 border-gray-200" />
        <h2 className="text-lg font-semibold text-forest mb-1">Security Question</h2>
        <p className="text-sm text-gray-600 mb-1">
          If you ever forget your password, we will ask you this question to
          make sure it is really you. Choose one you will always remember.
        </p>

        {questionsError && (
          <p className="text-red-600 text-sm mt-2">
            Could not load the security questions. {questionsError}
          </p>
        )}

        <label className={labelClass}>Choose your question</label>
        <select
          className={inputClass}
          name="security_question"
          value={form.security_question}
          onChange={handleChange}
          required
        >
          {questions.length === 0 && <option value="">Loading questions...</option>}
          {questions.map((q) => (
            <option key={q.id} value={q.id}>
              {q.question_en}
            </option>
          ))}
        </select>

        {/* Show the Hindi version of whichever question is selected, so an
            artisan who reads Hindi more comfortably still understands it. */}
        {questions.find((q) => q.id === form.security_question) && (
          <p className="text-sm text-gray-500 mt-1">
            {questions.find((q) => q.id === form.security_question).question_hi}
          </p>
        )}

        <label className={labelClass}>Your answer</label>
        <input
          className={inputClass}
          name="security_answer"
          value={form.security_answer}
          onChange={handleChange}
          placeholder="Write your answer here"
          required
        />
        <p className="text-xs text-gray-500 mt-1">
          Capital letters and extra spaces do not matter. Keep this answer private.
        </p>

        <hr className="my-6 border-gray-200" />
        <h2 className="text-lg font-semibold text-forest mb-2">Your Business</h2>

        <label className={labelClass}>Business / Craft Name</label>
        <input className={inputClass} name="business_name" value={form.business_name} onChange={handleChange} required />

        <label className={labelClass}>Craft Category</label>
        <select className={inputClass} name="craft_category" value={form.craft_category} onChange={handleChange}>
          {CRAFT_CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
        </select>

        <label className={labelClass}>Describe your business</label>
        <textarea className={inputClass} name="description" rows={3} value={form.description} onChange={handleChange} />

        <label className={labelClass}>Location (City/Town)</label>
        <input className={inputClass} name="location" value={form.location} onChange={handleChange} />

        <label className={labelClass}>State</label>
        <select className={inputClass} name="state" value={form.state} onChange={handleChange}>
          {INDIAN_STATES.map((s) => <option key={s} value={s}>{s}</option>)}
        </select>

        {error && <p className="text-red-600 text-sm mt-4">{error}</p>}

        <button
          type="submit"
          disabled={loading}
          className="w-full bg-terracotta text-white font-semibold py-3 rounded-full mt-6 shadow-md disabled:opacity-60"
        >
          {loading ? 'Creating your account...' : 'Create Account'}
        </button>
      </form>

      <p className="text-center mt-4 text-gray-600">
        Already have an account?{' '}
        <Link to="/login" className="text-forest font-medium underline">Log in</Link>
      </p>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import { getMyStorefront, storeQrUrl, storePublicUrl } from '../services/api.js'
import { useAuth } from '../services/AuthContext.jsx'

export default function Store() {
  const { token } = useAuth()
  const [business, setBusiness] = useState(null)
  const [error, setError] = useState('')
  const [copied, setCopied] = useState(false)

  useEffect(() => {
    getMyStorefront(token).then(setBusiness).catch((err) => setError(err.message))
  }, [token])

  async function handleShare() {
    const url = storePublicUrl(business.slug)
    if (navigator.share) {
      try {
        await navigator.share({ title: business.business_name, url })
        return
      } catch {
        // user cancelled the native share sheet - fall through to copy
      }
    }
    await navigator.clipboard.writeText(url)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  if (error) return <p className="text-red-600 p-5 text-center">{error}</p>
  if (!business) return <p className="text-gray-500 p-5 text-center">Loading...</p>

  return (
    <div className="p-5">
      {!business.is_published && (
        <div className="bg-sand/30 border border-sand text-charcoal text-sm rounded-lg p-3 mb-4">
          Your store isn't published yet — visitors can't see it.{' '}
          <Link to="/digitalise" className="underline font-medium">Publish it here</Link>.
        </div>
      )}

      <div className="bg-white rounded-xl p-5 shadow-sm text-center mb-4">
        <h2 className="text-xl font-bold text-forest">{business.business_name}</h2>
        <p className="text-sm text-gray-500 mb-4">{business.craft_category}</p>

        <img
          src={storeQrUrl(business.slug)}
          alt="Store QR code"
          className="w-48 h-48 mx-auto border border-gray-200 rounded-lg p-2"
        />
        <p className="text-xs text-gray-400 mt-2 break-all">{storePublicUrl(business.slug)}</p>

        <button
          onClick={handleShare}
          className="w-full bg-terracotta text-white font-semibold py-3 rounded-full mt-4 shadow-md"
        >
          {copied ? 'Link Copied ✓' : '📤 Share My Store'}
        </button>
      </div>

      <Link
        to={`/store/${business.slug}`}
        target="_blank"
        className="block text-center w-full border border-forest text-forest font-semibold py-3 rounded-full mb-3"
      >
        Preview as a Visitor
      </Link>
      <Link
        to="/digitalise"
        className="block text-center w-full text-gray-500 py-2"
      >
        Edit Storefront Settings
      </Link>
    </div>
  )
}

import { createContext, useContext, useEffect, useState } from 'react'
import { getMe } from './api.js'

const AuthContext = createContext(null)
const TOKEN_KEY = 'shilpsetu_token'

// Makes "who is logged in right now" available to every screen in the
// app, without passing it down through every single component by hand.
// This is called a "React Context" - think of it as a small shared box
// of data that any page can read from using the useAuth() hook below.
export function AuthProvider({ children }) {
  const [token, setToken] = useState(() => localStorage.getItem(TOKEN_KEY))
  const [user, setUser] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (!token) {
      setUser(null)
      setLoading(false)
      return
    }
    getMe(token)
      .then(setUser)
      .catch(() => {
        // Token is invalid or expired - clear it and send the user to log in again.
        localStorage.removeItem(TOKEN_KEY)
        setToken(null)
        setUser(null)
      })
      .finally(() => setLoading(false))
  }, [token])

  function login(newToken, newUser) {
    localStorage.setItem(TOKEN_KEY, newToken)
    setToken(newToken)
    setUser(newUser)
  }

  function logout() {
    localStorage.removeItem(TOKEN_KEY)
    setToken(null)
    setUser(null)
  }

  return (
    <AuthContext.Provider value={{ token, user, setUser, loading, login, logout }}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  return useContext(AuthContext)
}

export const BASE_URL = "http://localhost:8010"

// A small wrapper around the browser's built-in "fetch" function for
// JSON requests. It attaches the login token when we have one, and
// throws a readable error message when the backend responds with a
// failure status code.
async function request(path, { method = "GET", body, token } = {}) {
  const headers = { "Content-Type": "application/json" }
  if (token) headers["Authorization"] = `Bearer ${token}`

  let res
  try {
    res = await fetch(`${BASE_URL}${path}`, {
      method,
      headers,
      body: body ? JSON.stringify(body) : undefined,
    })
  } catch (networkError) {
    throw new Error("Could not reach the server. Is the backend running?")
  }

  const data = await res.json().catch(() => null)

  if (!res.ok) {
    const message = data?.detail || "Something went wrong. Please try again."
    throw new Error(typeof message === "string" ? message : "Something went wrong. Please try again.")
  }

  return data
}

// Same idea, but for requests that carry a file (FormData) instead of
// JSON - used for creating/updating products with a photo. We do NOT
// set a Content-Type header ourselves: the browser sets the correct
// "multipart/form-data; boundary=..." header automatically for FormData.
export async function requestForm(path, { method = "POST", formData, token } = {}) {
  const headers = {}
  if (token) headers["Authorization"] = `Bearer ${token}`

  let res
  try {
    res = await fetch(`${BASE_URL}${path}`, { method, headers, body: formData })
  } catch (networkError) {
    throw new Error("Could not reach the server. Is the backend running?")
  }

  const data = await res.json().catch(() => null)

  if (!res.ok) {
    const message = data?.detail || "Something went wrong. Please try again."
    throw new Error(typeof message === "string" ? message : "Something went wrong. Please try again.")
  }

  return data
}

// Turns a relative image path from the backend (e.g. "/uploads/products/x.jpg")
// into a full URL an <img> tag can load.
export function imageUrl(path) {
  if (!path) return null
  return `${BASE_URL}${path}`
}

